    for row in ws.iter_rows(min_row=2, values_only=True):
        if not row or row[0] is None: continue
        cluster, identity, classification, celltype = row[0], row[1], row[2], row[3]
        markers=[m for m in row[4:9] if m]
        if markers:
            marker_rows.append((sheet,str(identity),str(classification),markers))
print('rows',len(marker_rows))

def find_genes(m):
    # normalize marker: split slash, parentheses, dots
    tokens=[]
    for part in re.split(r'[/,()]', m):
        part=part.strip().rstrip('+')
        if part:
            tokens.append(part)
    hits=[]
    for tok in tokens:
        # exact case-insensitive, then substring
        exact=[x for x in g.index if x.upper()==tok.upper()]
        if exact: hits.extend(exact)
        else:
            # regex with boundaries; avoid too broad
            pat=re.compile(re.escape(tok), re.I)
            sub=[x for x in g.index if pat.search(x)]
            # if too many, choose exact word or containing token at start
            if len(sub)>20:
                sub=[x for x in sub if tok.lower() in x.lower() and (x.upper().startswith(tok.upper()) or x.upper()==tok.upper())][:5]
            hits.extend(sub[:5])
    return list(dict.fromkeys(hits))

# For each marker row, compute max column for mean of marker expr (log)
confusion=[]
for sheet, ident, cls, markers in marker_rows:
    genes=[]
    for m in markers:
        genes.extend(find_genes(m))
    genes=list(dict.fromkeys(genes))
    if not genes: continue
    avg=log.loc[genes].mean(axis=0)
    maxcol=avg.idxmax()
    maxval=avg.max()
