        exp='epidermis'
    elif 'neural' in ident_l or 'cns' in ident_l or 'pigment' in ident_l or 'neuron' in ident_l or 'glia' in ident_l:
        exp='neural'
    elif 'notochord' in ident_l or 'mesoderm' in ident_l or 'somite' in ident_l or 'muscle' in ident_l:
        # distinguish somite vs mesodermal_notochord etc
